// ============================================================================
// VIRAASAT — Supabase Custom Send SMS Hook (Deno Edge Function -> MSG91)
// Receives the exact 6-digit OTP generated by Supabase Auth, verifies the
// Standard Webhooks HMAC-SHA256 signature, and forwards the OTP to MSG91.
//
// Deploy with:
//   supabase functions deploy send-sms-hook --no-verify-jwt
// Set secrets with:
//   supabase secrets set SUPABASE_SMS_HOOK_SECRET="v1,whsec_..."
//   supabase secrets set MSG91_AUTH_KEY="..."
//   supabase secrets set MSG91_TEMPLATE_ID="..."
// ============================================================================

import { Webhook } from 'https://esm.sh/standardwebhooks@1.0.0';

interface SendSmsHookPayload {
  user: {
    id: string;
    phone: string;
    email?: string;
  };
  sms: {
    otp: string;
  };
}

function normalizeIndianPhoneForMsg91(rawPhone: string): string | null {
  const cleaned = rawPhone.trim().replace(/[\s\-()]/g, '');
  if (/^\+91[6-9]\d{9}$/.test(cleaned)) {
    return cleaned.slice(1); // 91XXXXXXXXXX
  }
  if (/^91[6-9]\d{9}$/.test(cleaned)) {
    return cleaned;
  }
  return null;
}

Deno.serve(async (req: Request) => {
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: { message: 'Method not allowed' } }), {
      status: 405,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const hookSecret = (Deno.env.get('SUPABASE_SMS_HOOK_SECRET') || '').trim();
  const msg91AuthKey = (Deno.env.get('MSG91_AUTH_KEY') || '').trim();
  const msg91TemplateId = (Deno.env.get('MSG91_TEMPLATE_ID') || '').trim();
  const otpVarName = (Deno.env.get('MSG91_OTP_VAR_NAME') || 'otp').trim();

  if (!hookSecret || !msg91AuthKey || !msg91TemplateId) {
    console.error('Missing SUPABASE_SMS_HOOK_SECRET, MSG91_AUTH_KEY, or MSG91_TEMPLATE_ID');
    return new Response(
      JSON.stringify({
        error: {
          http_code: 500,
          message: 'SMS Hook credentials are not configured on Supabase Edge Functions.',
        },
      }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }

  const rawBody = await req.text();
  const headers = Object.fromEntries(req.headers.entries());

  let payload: SendSmsHookPayload;
  try {
    // Strip Supabase's `v1,` prefix before passing `whsec_...` to Standard Webhooks verifier
    const standardSecret = hookSecret.replace(/^v1,/, '');
    const wh = new Webhook(standardSecret);
    payload = wh.verify(rawBody, headers) as SendSmsHookPayload;
  } catch (err) {
    console.error('Invalid Supabase SMS Hook signature:', err);
    return new Response(
      JSON.stringify({
        error: {
          http_code: 401,
          message: 'Unauthorized webhook signature.',
        },
      }),
      { status: 401, headers: { 'Content-Type': 'application/json' } }
    );
  }

  const msg91Mobile = normalizeIndianPhoneForMsg91(payload?.user?.phone || '');
  const otp = (payload?.sms?.otp || '').trim();

  if (!msg91Mobile) {
    return new Response(
      JSON.stringify({
        error: {
          http_code: 400,
          message: 'Only valid Indian mobile numbers with +91 country code are supported.',
        },
      }),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  if (!/^\d{6}$/.test(otp)) {
    return new Response(
      JSON.stringify({
        error: {
          http_code: 400,
          message: 'Invalid 6-digit OTP payload from Supabase Auth.',
        },
      }),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  // Forward the EXACT Supabase-generated OTP to MSG91 Flow v5 API
  const recipient: Record<string, string> = {
    mobiles: msg91Mobile,
    otp,
    var1: otp,
  };
  if (otpVarName && otpVarName !== 'otp' && otpVarName !== 'var1') {
    recipient[otpVarName] = otp;
  }

  try {
    const msg91Response = await fetch('https://control.msg91.com/api/v5/flow', {
      method: 'POST',
      headers: {
        authkey: msg91AuthKey,
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify({
        template_id: msg91TemplateId,
        short_url: '0',
        recipients: [recipient],
      }),
    });

    const bodyText = await msg91Response.text();
    let msg91Data: { type?: string; message?: string; request_id?: string } = {};
    try {
      msg91Data = JSON.parse(bodyText);
    } catch {
      msg91Data = { message: bodyText };
    }

    if (!msg91Response.ok || msg91Data.type === 'error') {
      console.error('MSG91 gateway rejected SMS OTP:', msg91Response.status, bodyText);
      return new Response(
        JSON.stringify({
          error: {
            http_code: 502,
            message: `MSG91 SMS delivery failed: ${msg91Data.message || msg91Response.statusText}`,
          },
        }),
        { status: 502, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Returning HTTP 200 informs Supabase Auth that MSG91 accepted dispatch.
    // The user's phone is NOT marked verified until supabase.auth.verifyOtp() succeeds.
    return new Response(JSON.stringify({}), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    console.error('MSG91 network error:', err);
    return new Response(
      JSON.stringify({
        error: {
          http_code: 502,
          message: 'Unable to reach MSG91 SMS gateway.',
        },
      }),
      { status: 502, headers: { 'Content-Type': 'application/json' } }
    );
  }
});
